      {
        find: /^react-native-svg$/,
        replacement: resolve(__dirname, '__mocks__/react-native-svg.ts'),
      },
    ],
  },
  esbuild: {
    jsx: 'automatic',
    jsxImportSource: 'react',
  },
})

