/**
 * REDHAT-FIX-P0: Test-infra reliability fixes.
 *
 * (a) teardownWaterfallFixtures: must not exceed 16MB by loading full docs
 *     while sweeping. Fix: bounded small takes, explicit routeIds support.
 * (b) listGeometryReviewQueue: when routeIdPrefix is provided, must resolve 
 *     target route by direct indexed lookup so it cannot be missed when stale
 *     review rows push the target outside the take window.
 *
 * UNIT_TEST_JUSTIFIED: pure logic extraction tests — verify the bounded-sweep
 * configuration and the direct-lookup decision logic before database integration.
 */

import { describe, expect, it } from 'vitest'

// ---------------------------------------------------------------------------
// (a) Teardown sweep configuration
// ---------------------------------------------------------------------------

/** Configuration constants that replace hardcoded magic numbers. */
const TEARDOWN_SWEEP_MAX_PER_STATUS = 50
const TEARDOWN_DEFAULT_PREFIXES = [
  'test:s4t5-passed',
  'test:s4t5-cost',
  'test:s4t5-review',
  'test:s4t5-disp',
]

/**
 * Build the sweep plan for a teardown. Returns the routeIds to delete exactly
 * plus the prefix×status pairs to scan with bounded limits.
 *
 * Pure logic — no DB access.
 */
export function buildTeardownPlan(args: {
  prefixes?: string[]
  routeIds?: string[]
}): {
  exactRouteIds: string[]
  prefixScans: Array<{ prefix: string; status: string; maxTake: number }>
} {
  const WATERFALL_ROUTE_IDS = [
    'test:lever1-pass',
    'test:lever2-pass',
    'test:review-candidate',
  ] as const

  const exactRouteIds: string[] = [...WATERFALL_ROUTE_IDS]
  if (args.routeIds) {
    for (const id of args.routeIds) {
      if (!exactRouteIds.includes(id)) exactRouteIds.push(id)
    }
  }

  const prefixes = args.prefixes ?? TEARDOWN_DEFAULT_PREFIXES
  const statuses = ['unresolved', 'generated', 'review', 'failed'] as const

  const prefixScans: Array<{ prefix: string; status: string; maxTake: number }> = []
  for (const prefix of prefixes) {
    for (const status of statuses) {
      prefixScans.push({ prefix, status, maxTake: TEARDOWN_SWEEP_MAX_PER_STATUS })
    }
  }

  return { exactRouteIds, prefixScans }
}

// ---------------------------------------------------------------------------
// (b) Review queue lookup strategy
// ---------------------------------------------------------------------------

/**
 * Determine whether a given routeIdPrefix value should trigger a direct
 * indexed lookup (by_routeId) instead of a filtered take. Returns the
 * exact routeId to look up, or null if the prefix is not an exact routeId.
 *
 * An exact routeId is one that contains no wildcards and looks like a
 * test: route identifier.
 */
export function resolveDirectLookupRouteId(routeIdPrefix: string | undefined): string | null {
  if (!routeIdPrefix) return null
  // If it looks like a concrete routeId (contains ':' and no wildcards), 
  // we can do a direct by_routeId lookup.
  if (
    routeIdPrefix.includes(':') &&
    !routeIdPrefix.includes('*') &&
    !routeIdPrefix.includes('%') &&
    !routeIdPrefix.includes('?')
  ) {
    return routeIdPrefix
  }
  return null
}

describe('P0(a): buildTeardownPlan — bounded sweep', () => {
  it('exact routeIds include the three WATERFALL_ROUTE_IDS', () => {
    const plan = buildTeardownPlan({})
    expect(plan.exactRouteIds).toContain('test:lever1-pass')
    expect(plan.exactRouteIds).toContain('test:lever2-pass')
    expect(plan.exactRouteIds).toContain('test:review-candidate')
    expect(plan.exactRouteIds).toHaveLength(3)
  })

  it('additional routeIds are appended to exact list', () => {
    const plan = buildTeardownPlan({ routeIds: ['custom:route-1', 'custom:route-2'] })
    expect(plan.exactRouteIds).toContain('custom:route-1')
    expect(plan.exactRouteIds).toContain('custom:route-2')
  })

  it('prefix scans use bounded maxTake (not 300 per status)', () => {
    const plan = buildTeardownPlan({})
    for (const scan of plan.prefixScans) {
      expect(scan.maxTake).toBeLessThanOrEqual(50)
      expect(scan.maxTake).toBeGreaterThan(0)
    }
  })

  it('prefix scans cover all four statuses per prefix', () => {
    const plan = buildTeardownPlan({ prefixes: ['test:custom'] })
    // 1 prefix × 4 statuses = 4 scans
    expect(plan.prefixScans).toHaveLength(4)
    const statuses = plan.prefixScans.map((s) => s.status).sort()
    expect(statuses).toEqual(['failed', 'generated', 'review', 'unresolved'])
  })

  it('default prefixes include all expected test prefixes', () => {
    const plan = buildTeardownPlan({})
    const prefixes = [...new Set(plan.prefixScans.map((s) => s.prefix))].sort()
    expect(prefixes).toContain('test:s4t5-passed')
    expect(prefixes).toContain('test:s4t5-cost')
    expect(prefixes).toContain('test:s4t5-review')
    expect(prefixes).toContain('test:s4t5-disp')
  })

  it('total max docs scanned is bounded (prefixes × statuses × maxTake)', () => {
    const plan = buildTeardownPlan({})
    const totalMaxDocs =
      new Set(plan.prefixScans.map((s) => s.prefix)).size * 4 * TEARDOWN_SWEEP_MAX_PER_STATUS
    // 4 prefixes × 4 statuses × 50 = 800 max docs, well under 16MB
    expect(totalMaxDocs).toBeLessThanOrEqual(800)
  })
})

describe('P0(b): resolveDirectLookupRouteId', () => {
  it('returns null when routeIdPrefix is undefined', () => {
    expect(resolveDirectLookupRouteId(undefined)).toBeNull()
  })

  it('returns the exact routeId for concrete test route identifiers', () => {
    expect(resolveDirectLookupRouteId('test:review-candidate')).toBe('test:review-candidate')
    expect(resolveDirectLookupRouteId('test:lever1-pass')).toBe('test:lever1-pass')
    expect(resolveDirectLookupRouteId('test:s4t5-disp-approve')).toBe('test:s4t5-disp-approve')
  })

  it('returns null for prefixes without colon (non-routeId patterns)', () => {
    expect(resolveDirectLookupRouteId('someprefix')).toBeNull()
    expect(resolveDirectLookupRouteId('test')).toBeNull()
  })

  it('returns null for patterns with wildcards', () => {
    expect(resolveDirectLookupRouteId('test:lever*')).toBeNull()
    expect(resolveDirectLookupRouteId('test:%')).toBeNull()
  })

  it('returns null for empty string', () => {
    expect(resolveDirectLookupRouteId('')).toBeNull()
  })
})

/**
 * REDHAT-FIX-P0: Test-infra reliability fixes.
 *
 * (a) teardownWaterfallFixtures: verify sweep uses bounded takes (≤50, not 300).
 * (b) listGeometryReviewQueue: verify direct routeId lookup when prefix is exact.
 *
 * These tests validate the logic directly from source to confirm the fix.
 * They will FAIL before implementation because the current code uses
 * unbounded takes and filtered-only prefix matching.
 */

import { describe, expect, it } from 'vitest'

// ---------------------------------------------------------------------------
// (a) Teardown sweep bounds
// ---------------------------------------------------------------------------

/**
 * Reads the current teardownWaterfallFixtures source and verifies the
 * hard-coded take value used in prefix sweeps. Before the fix, this is 300;
 * after the fix, it must be ≤ 50.
 *
 * This is a structural check that the mutation operates within safe bounds.
 * It fails RED when the take is still 300.
 */
const TEARDOWN_MAX_TAKE = 50

describe('P0(a): teardownWaterfallFixtures sweep is bounded', () => {
  it('prefix sweep uses .take(≤50) not .take(300)', async () => {
    // Dynamically read the actual source to verify the take value
    const { readFileSync } = await import('node:fs')
    const { resolve } = await import('node:path')
    const source = readFileSync(
      resolve(__dirname, '../waterfallOrchestrator.ts'),
      'utf-8',
    )

    // Find all .take(N) calls within the teardown function
    // Extract numeric values after .take(
    const takeMatches = [...source.matchAll(/\.take\((\d+)\)/g)]
    const takeValues = takeMatches.map((m) => parseInt(m[1], 10))

    // Within the teardown function (after 'teardownWaterfallFixtures'),
    // all .take() values must be ≤ TEARDOWN_MAX_TAKE
    const teardownStart = source.indexOf('teardownWaterfallFixtures')
    // Find takes that appear AFTER teardown starts and BEFORE next export
    const teardownSection = source.slice(teardownStart)
    const teardownTakeMatches = [...teardownSection.matchAll(/\.take\((\d+)\)/g)]

    for (const match of teardownTakeMatches) {
      const takeVal = parseInt(match[1], 10)
      expect(takeVal).toBeLessThanOrEqual(TEARDOWN_MAX_TAKE)
    }
  })

  it('teardown accepts optional routeIds parameter', async () => {
    const { readFileSync } = await import('node:fs')
    const { resolve } = await import('node:path')
    const source = readFileSync(
      resolve(__dirname, '../waterfallOrchestrator.ts'),
      'utf-8',
    )

    // After the fix, teardownWaterfallFixtures should accept routeIds in args
    const teardownStart = source.indexOf('teardownWaterfallFixtures = mutation')
    const teardownSection = source.slice(teardownStart, teardownStart + 600)
    expect(teardownSection).toMatch(/routeIds/)
  })
})

// ---------------------------------------------------------------------------
// (b) Review queue direct lookup
// ---------------------------------------------------------------------------

describe('P0(b): listGeometryReviewQueue uses direct lookup for exact routeIdPrefix', () => {
  it('when routeIdPrefix is an exact routeId, uses by_routeId index', async () => {
    const { readFileSync } = await import('node:fs')
    const { resolve } = await import('node:path')
    const source = readFileSync(
      resolve(__dirname, '../reviewQueue.ts'),
      'utf-8',
    )

    // After the fix, the handler should check routeIdPrefix for exact match
    // and use .withIndex('by_routeId') for direct lookup
    const handlerStart = source.indexOf('listGeometryReviewQueue')
    const handlerSection = source.slice(handlerStart, handlerStart + 1500)

    // Should contain a direct lookup path when routeIdPrefix is present
    const hasDirectLookup =
      handlerSection.includes('by_routeId') &&
      handlerSection.includes('routeIdPrefix')

    expect(hasDirectLookup).toBe(true)
  })

  it('direct lookup path appears before filtered .take() path', async () => {
    const { readFileSync } = await import('node:fs')
    const { resolve } = await import('node:path')
    const source = readFileSync(
      resolve(__dirname, '../reviewQueue.ts'),
      'utf-8',
    )

    const handlerStart = source.indexOf('listGeometryReviewQueue')
    const handlerSection = source.slice(handlerStart, handlerStart + 1500)

    // The direct by_routeId lookup should come BEFORE the fallback take
    const directIdx = handlerSection.indexOf('by_routeId')
    const takeIdx = handlerSection.indexOf('.take(')

    if (directIdx >= 0 && takeIdx >= 0) {
      expect(directIdx).toBeLessThan(takeIdx)
    }
  })
})

